#!/usr/bin/env python3
"""Regenerates saa_cjson_prefix.h from cJSON.h: every CJSON_PUBLIC function gets
a saa_ prefix, so the vendored copy cannot clash with another cJSON in the same
program. Run it after updating cJSON.

usage: python3 gen_prefix.py
"""
import os
import re

HERE = os.path.dirname(os.path.abspath(__file__))

with open(os.path.join(HERE, "cJSON.h")) as f:
    names = sorted(set(re.findall(r"CJSON_PUBLIC\([^)]*\)\s*\**\s*(cJSON_\w+)\s*\(", f.read())))

lines = [
    "/* Generated by gen_prefix.py from cJSON.h; do not edit. */",
    "#ifndef SAA_CJSON_PREFIX_H",
    "#define SAA_CJSON_PREFIX_H",
    "",
]
lines += [f"#define {n} saa_{n}" for n in names]
lines += ["", "#endif /* SAA_CJSON_PREFIX_H */", ""]
with open(os.path.join(HERE, "saa_cjson_prefix.h"), "w") as f:
    f.write("\n".join(lines))
print(f"{len(names)} names")
